pub fn parse_port(value: &str) -> Result<u16, String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return Err("port is empty".to_string());
    }
    trimmed
        .parse::<u16>()
        .map_err(|_| format!("invalid TCP/UDP port: {value}"))
}

