    if (dst == NULL || src == NULL || dst_size == 0) {
        return -1;
    }
    size_t src_len = strlen(src);
    if (src_len >= dst_size) {
        dst[0] = '\0';
        return -2;
    }
    memcpy(dst, src, src_len + 1);
    return 0;
}
